// Pure-JS CRC32 & ZIP builder (STORE method=0, 100% compatible with Excel, WPS, Numbers, Google Sheets)
(function() {
  const crcTable = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    }
    crcTable[n] = c >>> 0;
  }

  function crc32(u8) {
    let c = 0xffffffff;
    for (let i = 0; i < u8.length; i++) {
      c = crcTable[(c ^ u8[i]) & 0xff] ^ (c >>> 8);
    }
    return (c ^ 0xffffffff) >>> 0;
  }

  function b64ToUint8(b64) {
    const bin = atob(b64);
    const u8 = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return u8;
  }

  function strToUint8(str) {
    return new TextEncoder().encode(str);
  }

  function escapeXml(str) {
    return String(str ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  // Patch cell values into xl/worksheets/sheet1.xml while preserving 100% of original cell styles (s="...")
  function patchSheetXml(baseXml, cellMap) {
    let xml = baseXml;
    for (const [cellRef, rawVal] of Object.entries(cellMap)) {
      if (rawVal === undefined || rawVal === null) continue;
      const valStr = String(rawVal).trim();
      const re = new RegExp('<c\\s+r="' + cellRef + '"([^>]*?)(?:/>|>([\\s\\S]*?)</c>)');
      xml = xml.replace(re, function(match, attrs) {
        const cleanAttrs = attrs.replace(/\s+t="[^"]*"/g, '');
        if (valStr === '') {
          return '<c r="' + cellRef + '"' + cleanAttrs + '/>';
        }
        const isPureNumber = /^-?\d+(\.\d+)?$/.test(valStr) && !/^0\d+$/.test(valStr);
        if (isPureNumber) {
          return '<c r="' + cellRef + '"' + cleanAttrs + '><v>' + valStr + '</v></c>';
        }
        return '<c r="' + cellRef + '"' + cleanAttrs + ' t="inlineStr"><is><t>' + escapeXml(valStr) + '</t></is></c>';
      });
    }
    return xml;
  }

  function buildZipBlob(entries) {
    const localParts = [];
    const centralParts = [];
    let offset = 0;

    for (const entry of entries) {
      const nameBytes = strToUint8(entry.name);
      const dataBytes = entry.data;
      const crc = crc32(dataBytes);
      const size = dataBytes.length;

      const lh = new Uint8Array(30 + nameBytes.length);
      const ldv = new DataView(lh.buffer);
      ldv.setUint32(0, 0x04034b50, true);
      ldv.setUint16(4, 20, true);
      ldv.setUint16(6, 0x0800, true);
      ldv.setUint16(8, 0, true);
      ldv.setUint16(10, 0, true);
      ldv.setUint16(12, 0x5978, true);
      ldv.setUint32(14, crc, true);
      ldv.setUint32(18, size, true);
      ldv.setUint32(22, size, true);
      ldv.setUint16(26, nameBytes.length, true);
      ldv.setUint16(28, 0, true);
      lh.set(nameBytes, 30);

      localParts.push(lh, dataBytes);

      const ch = new Uint8Array(46 + nameBytes.length);
      const cdv = new DataView(ch.buffer);
      cdv.setUint32(0, 0x02014b50, true);
      cdv.setUint16(4, 20, true);
      cdv.setUint16(6, 20, true);
      cdv.setUint16(8, 0x0800, true);
      cdv.setUint16(10, 0, true);
      cdv.setUint16(12, 0, true);
      cdv.setUint16(14, 0x5978, true);
      cdv.setUint32(16, crc, true);
      cdv.setUint32(20, size, true);
      cdv.setUint32(24, size, true);
      cdv.setUint16(28, nameBytes.length, true);
      cdv.setUint16(30, 0, true);
      cdv.setUint16(32, 0, true);
      cdv.setUint16(34, 0, true);
      cdv.setUint16(36, 0, true);
      cdv.setUint32(38, 0, true);
      cdv.setUint32(42, offset, true);
      ch.set(nameBytes, 46);

      centralParts.push(ch);
      offset += lh.length + dataBytes.length;
    }

    const centralSize = centralParts.reduce((s, p) => s + p.length, 0);
    const eocd = new Uint8Array(22);
    const edv = new DataView(eocd.buffer);
    edv.setUint32(0, 0x06054b50, true);
    edv.setUint16(4, 0, true);
    edv.setUint16(6, 0, true);
    edv.setUint16(8, entries.length, true);
    edv.setUint16(10, entries.length, true);
    edv.setUint32(12, centralSize, true);
    edv.setUint32(16, offset, true);
    edv.setUint16(20, 0, true);

    return new Blob([...localParts, ...centralParts, eocd], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    });
  }

  window.generateTemplateXlsxBlob = function(templateKey, cellMap) {
    const tpl = window.BRAUN_ORDER_TEMPLATES[templateKey];
    if (!tpl) throw new Error('Unknown template: ' + templateKey);
    const patchedXml = patchSheetXml(tpl.sheetXml, cellMap);
    const entries = [];
    for (const [fn, b64] of Object.entries(tpl.files)) {
      entries.push({ name: fn, data: b64ToUint8(b64) });
    }
    entries.push({ name: 'xl/worksheets/sheet1.xml', data: strToUint8(patchedXml) });
    return buildZipBlob(entries);
  };
})();
